import{_ as s,a0 as i,w as p,s as l,ao as C,I as a,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"LinuxCon: 服務器操作系統的轉型 | LCTT x X-CMD","titleTemplate":false,"description":"LinuxCon: 服務器操作系統的轉型 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LinuxCon: 服務器操作系統的轉型 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LinuxCon: 服務器操作系統的轉型 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150819 Linuxcon--The Changing Role of the Server OS","title":"LinuxCon: 服務器操作系統的轉型","tag":"201509","desc":""},"relativePath":"201509/20150819 Linuxcon--The Changing Role of the Server OS.md","filePath":"[post].md"}'),u={name:"201509/20150819 Linuxcon--The Changing Role of the Server OS.md"};function x(m,e,h,d,f,T){const r=i("Link");return p(),l("div",null,[e[13]||(e[13]=C('<h1 id="linuxcon-服務器操作系統的轉型" tabindex="-1">LinuxCon: 服務器操作系統的轉型 <a class="header-anchor" href="#linuxcon-服務器操作系統的轉型" aria-label="Permalink to “LinuxCon: 服務器操作系統的轉型”">​</a></h1><p>西雅圖報道。容器遲早要改變世界，以及改變操作系統的角色。這是 Wim Coekaerts 帶來的 LinuxCon 演講主題，Coekaerts 是 Oracle 公司 Linux 與虛擬化工程的高級副總裁。</p><p><img src="http://www.serverwatch.com/imagesvr_ce/6421/wim-200x150.jpg" alt=""></p><p>Coekaerts 在開始演講的時候拿出一張關於“桌面之年”的幻燈片，引發了現場觀眾的一片笑聲。之後他説 2015 年很明顯是容器之年，更是應用之年，應用才是容器的關鍵。</p><p>“你需要操作系統做什麼事情？”，Coekaerts 回答現場觀眾：“只需一件事：運行一個應用。操作系統負責管理硬件和資源，來讓你的應用運行起來。”</p><p>Coakaerts 補充説，在 Docker 容器的幫助下，我們的注意力再次集中在應用上，而在 Oracle，我們將注意力放在如何讓應用更好地運行在操作系統上。</p><p>“許多人過去常常需要繁瑣地安裝應用，而現在的年輕人只需要按一個按鈕就能讓應用在他們的移動設備上運行起來”。</p><p>人們對安裝企業版的軟件需要這麼複雜的步驟而感到驚訝，而 Docker 幫助他們脱離了這片苦海。</p><p>“操作系統的角色已經變了。” Coekaerts 説。</p><p>Docker 的出現不代表虛擬機的淘汰，容器化過程需要經過很長時間才能變得成熟，然後才能在世界範圍內得到應用。</p><p>在這段時間內，容器會與虛擬機共存，並且我們需要一些工具，將應用在容器和虛擬機之間進行轉換遷移。Coekaerts 舉例説 Oracle 的 VirtualBox 就可以用來幫助用户運行 Docker，而它原來是被廣泛用在桌面系統上的一項開源技術。現在 Docker 的 Kitematic 項目將在 Mac 上使用 VirtualBox 運行 Docker。</p><h3 id="容器的開放計算計劃和一次寫隨處部署" tabindex="-1">容器的開放計算計劃和一次寫隨處部署 <a class="header-anchor" href="#容器的開放計算計劃和一次寫隨處部署" aria-label="Permalink to “容器的開放計算計劃和一次寫隨處部署”">​</a></h3><p>一個能讓容器成功的關鍵是“一次寫，隨處部署”的概念。而在容器之間的互操作領域，Linux 基金會的開放計算計劃（OCI）扮演一個非常關鍵的角色。</p><p>“使用 OCI，應用編譯一次後就可以很方便地在多地運行，所以你可以將你的應用部署在任何地方”。</p><p>Coekaerts 總結説雖然在遷移到容器模型過程中會發生很多好玩的事情，但容器還沒真正做好準備，他強調 Oracle 現在正在驗證將產品運行在容器內的可行性，但這是一個非常艱難的過程。</p><p>“運行資料庫很簡單，難的是要搞定資料庫所需的環境”，Coekaerts 説：“容器與虛擬機不一樣，一些需要依賴底層系統配置的應用無法從主機遷移到容器中。”</p><p>另外，Coekaerts 指出在容器內調試問題與在虛擬機內調試問題也是不一樣的，現在還沒有成熟的工具來進行容器應用的調試。</p><p>Coekaerts 強調當容器足夠成熟時，有一點很重要：不要拋棄現有的技術。組織和企業不能拋棄現有的部署好的應用，而完全投入新技術的懷抱。</p><p>“部署新技術是很困難的事情，你需要緩慢地遷移過去，能讓你順利遷移的技術才是成功的技術。”Coekaerts 説。</p><hr>',20)),a("p",null,[e[1]||(e[1]=t("via: ",-1)),o(r,{href:"http://www.serverwatch.com/server-news/linuxcon-the-changing-role-of-the-server-os.html"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.serverwatch.com/server-news/linuxcon-the-changing-role-of-the-server-os.html",-1)])]),_:1})]),a("p",null,[e[5]||(e[5]=t("作者：",-1)),o(r,{href:"http://www.serverwatch.com/author/Sean-Michael-Kerner-101580.htm"},{default:n(()=>[...e[2]||(e[2]=[t("Sean Michael Kerner",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),o(r,{href:"https://github.com/bazz2"},{default:n(()=>[...e[3]||(e[3]=[t("bazz2",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const w=s(u,[["render",x]]);export{g as __pageData,w as default};
